        // No fence at all: strip a conversational prefix if one is present.
        let text = response.trim();
        const lines = text.split(/\r?\n/);
        const codeStart = lines.findIndex((line) => /^\s*(?:#include|using\s+namespace|import\s+|package\s+|class\s+|public\s+|private\s+|def\s+|func\s+|impl\s+|fn\s+|SELECT\b|WITH\b|const\s+\w+\s*=|let\s+\w+\s*=|var\s+\w+\s*=)/i.test(line));
        if (codeStart > 0) text = lines.slice(codeStart).join('\n');
        return text.replace(/^```[a-z0-9+#]*\s*/i, '').replace(/```\s*$/i, '').trim();
    };

    // ============================================
    // AI PROVIDER (keyless DuckDuckGo proxy)
    // ============================================
    const AI_TIMEOUT_MS = 60000;

    const gmRequest = (details) => new Promise((resolve, reject) => {
        try {
            GM_xmlhttpRequest({
                method: details.method || 'POST',
                url: details.url,
                headers: details.headers || {},
                data: details.data,
                timeout: details.timeout || AI_TIMEOUT_MS,
                onload: (response) => {
                    if (response.status >= 200 && response.status < 300) {
                        resolve({ status: response.status, text: response.responseText || '' });
                    } else {
                        reject(new Error(`HTTP ${response.status}: ${String(response.responseText || '').slice(0, 200)}`));
                    }
                },
                onerror: (response) => reject(new Error('Network error' + (response && response.error ? `: ${response.error}` : ''))),
                ontimeout: () => reject(new Error('Request timed out')),
                onabort: () => reject(new Error('Request aborted')),
            });
        } catch (error) {
            reject(error);
        }
    });

    const postAIRequest = async (url, payload) => {
        // GM_xmlhttpRequest bypasses the page's Content-Security-Policy and CORS.
        // This is required because LeetCode's CSP only allows connections to
        // leetcode.com and challenges.cloudflare.com.
        if (typeof GM_xmlhttpRequest === 'function') {
            const response = await gmRequest({
                method: 'POST',
                url,
                headers: { 'Content-Type': 'application/json' },
                data: JSON.stringify(payload),
                timeout: AI_TIMEOUT_MS,
            });
            return response.text;
        }

        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), AI_TIMEOUT_MS);
        try {
            const response = await fetch(url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload),
                signal: controller.signal,
            });
            const text = await response.text();
            if (!response.ok) throw new Error(`HTTP ${response.status}: ${text.slice(0, 200)}`);
            return text;
        } finally {
            clearTimeout(timer);
        }
    };

    const generateWithDuckDuckGo = async (prompt) => {
        const preferred = SETTINGS.duckduckgoModel || 'gpt-oss-120b';
        const models = Array.from(new Set([preferred, 'gpt-oss-120b', 'gpt-5.4-mini', 'mistral-small-4', 'gemma-4-31b']));
        const baseUrl = (SETTINGS.duckduckgoApiUrl || 'https://duckduckgo-api.toontamilindia.workers.dev').replace(/\/+$/, '');
        const apiUrl = baseUrl.endsWith('/chat') ? baseUrl : baseUrl + '/chat';
        let lastError = null;

        for (const model of models) {
            try {
                const text = await postAIRequest(apiUrl, {
                    messages: [{ role: 'user', content: prompt }],
                    model,
                });
                const data = JSON.parse(text);
                const content = data && data.choices && data.choices[0] && data.choices[0].message
                    ? data.choices[0].message.content
                    : '';
                if (!content || !content.trim()) throw new Error('Empty response from AI');
                return content;
            } catch (error) {
                lastError = error;
                console.warn(`[LeetCode AI] Model "${model}" failed:`, error.message);
            }
        }

        throw lastError || new Error('No AI model is currently available');
    };

    // ============================================
    // AI SOLUTION GENERATOR
    // ============================================
    let isAiGenerationInProgress = false;
    let lastInjectedSolution = null;

    const setAIButtonLabel = (label) => {
        const button = document.getElementById('ai-solution-btn');
        if (!button) return;
        const labelEl = button.querySelector('[data-ai-label]');
        if (labelEl) labelEl.textContent = label;
        button.disabled = label === 'Generating...';
        button.style.opacity = button.disabled ? '0.7' : '1';
    };

    const generateAISolution = async (options = {}) => {
        const { auto = false, feedback = '' } = options;

        if (isAiGenerationInProgress) {
            showToast('AI generation is already running.', 'info', 2500);
            return null;
        }
        if (!SETTINGS.enableAISolver) {
            showToast('The AI solver is disabled in settings.', 'warning');
            return null;
        }

        const context = getProblemContext();
        if (!context.title) {
            showToast('Could not find the problem title. Open a LeetCode problem first.', 'error');
            return null;
        }
        if (!context.description) {
            showToast('Could not read the problem statement. Make sure the Description tab is open.', 'error');
            return null;
        }

        isAiGenerationInProgress = true;
        setAIButtonLabel('Generating...');
        if (!auto) showToast('Generating a solution...', 'info', 20000);

        try {
            // Wait for Monaco so the prompt contains the real starter signature.
            await waitForEditorModel(15000);
            const language = getSelectedLanguage();
            const starterCode = readEditorCode();
            if (!auto) showToast(`Generating a ${language.name} solution...`, 'info', 20000);
            const systemPrompt = (SETTINGS.aiSystemPrompt || DEFAULT_SETTINGS.aiSystemPrompt || '').trim();
            const prompt = [
                systemPrompt,
                '',
                `Language: ${language.name}`,
                `Problem: ${context.title}`,
                '',
                'Problem statement and examples:',
                context.description.slice(0, 18000),
                '',
                'Current editor starter code (keep its exact class/function signature):',
                starterCode.slice(0, 9000) || '(the editor is empty; write a complete solution for the requested language)',
                '',
                feedback ? `The previous attempt was rejected with: ${feedback}. Fix that and return a better solution.` : '',
                'Return ONLY the complete code that should replace the editor contents, inside one fenced code block.',
            ].filter(Boolean).join('\n');

            const response = await generateWithDuckDuckGo(prompt);
            const code = extractCode(response, language);

            if (!code || code.length < 5) throw new Error('The AI response did not contain usable code.');
            if (!setEditorCode(code)) throw new Error('Could not write the code into the LeetCode editor.');

            lastInjectedSolution = code;
            showToast(`AI solution inserted into the ${language.name} editor.`, 'success');
            setAIButtonLabel('Inserted');
            setTimeout(() => setAIButtonLabel('AI Solution'), 2500);
            return code;
        } catch (error) {
            console.error('[LeetCode AI] Generation failed:', error);
            showToast(`AI generation failed: ${error.message}`, 'error', 7000);
            setAIButtonLabel('AI Solution');
            return null;
        } finally {
            isAiGenerationInProgress = false;
        }
    };

    // ============================================
    // AI SOLUTION BUTTON
    // ============================================
    const AI_BUTTON_ID = 'ai-solution-btn';
    const AI_ICON = '<svg width="13" height="13" viewBox="0 0 24 24" aria-hidden="true" focusable="false" style="display:block;fill:currentColor;flex:none;"><path d="M12 2a3 3 0 0 1 3 3v1.06a6.002 6.002 0 0 1 3.94 3.94H20a3 3 0 1 1 0 6h-1.06a6.002 6.002 0 0 1-3.94 3.94V21a3 3 0 1 1-6 0v-1.06A6.002 6.002 0 0 1 5.06 16H4a3 3 0 1 1 0-6h1.06A6.002 6.002 0 0 1 9 6.06V5a3 3 0 0 1 3-3Zm0 6a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/></svg>';

    const findLeetCodeToolbar = () => {
        const runButton = qs('[data-e2e-locator="console-run-button"]');
        const submitButton = qs('[data-e2e-locator="console-submit-button"]');
        if (!runButton && !submitButton) return null;

        if (runButton && submitButton) {
            let el = runButton;
            while (el && !el.contains(submitButton)) el = el.parentElement;
            if (el) return el;
        }

        const anchor = runButton || submitButton;
        return anchor.parentElement && anchor.parentElement.parentElement
            ? anchor.parentElement.parentElement.parentElement
            : anchor.parentElement;
    };

    const TOOLBAR_BUTTON_STYLE = 'display:inline-flex;align-items:center;gap:6px;height:28px;margin-left:8px;padding:0 10px;border:0;border-radius:6px;background:linear-gradient(135deg,#7c3aed,#4f46e5);color:#fff;font:600 12px system-ui,-apple-system,Segoe UI,sans-serif;cursor:pointer;white-space:nowrap;box-shadow:0 1px 4px rgba(79,70,229,.35);line-height:1;';
    const FLOATING_BUTTON_STYLE = 'position:fixed;right:16px;bottom:64px;z-index:99999;display:inline-flex;align-items:center;gap:6px;height:34px;padding:0 14px;border:0;border-radius:8px;background:linear-gradient(135deg,#7c3aed,#4f46e5);color:#fff;font:600 13px system-ui,-apple-system,Segoe UI,sans-serif;cursor:pointer;white-space:nowrap;box-shadow:0 6px 18px rgba(79,70,229,.45);line-height:1;';

    const ensureAISolutionButton = () => {
        if (!SETTINGS.enableAISolver) return;

        const existing = document.getElementById(AI_BUTTON_ID);
        if (!isProblemPage() || !hasProblemUi()) {
            if (existing) existing.remove();
            return;
        }

        const toolbar = findLeetCodeToolbar();

        // LeetCode renders the Run/Submit toolbar after the script starts. If the
        // button was created as a floating fallback, move it into the real
        // toolbar as soon as the toolbar exists.
        if (existing && existing.isConnected) {
            if (toolbar && !toolbar.contains(existing)) {
                toolbar.appendChild(existing);
                existing.style.cssText = TOOLBAR_BUTTON_STYLE;
                console.log('[LeetCode AI] AI Solution button moved into the code toolbar');
            }
            return;
        }

        const button = document.createElement('button');
        button.id = AI_BUTTON_ID;
        button.type = 'button';
        button.title = 'Generate a solution with AI (LeetCode AI Solution Generator)';
        button.innerHTML = `${AI_ICON}<span data-ai-label>AI Solution</span>`;
        button.style.cssText = toolbar ? TOOLBAR_BUTTON_STYLE : FLOATING_BUTTON_STYLE;

        button.addEventListener('click', (event) => {
            event.preventDefault();
            event.stopPropagation();
            generateAISolution();
        });

        if (toolbar) {
            toolbar.appendChild(button);
            console.log('[LeetCode AI] AI Solution button added to the code toolbar');
        } else if (document.body) {
            document.body.appendChild(button);
            console.log('[LeetCode AI] AI Solution button added as a floating button');
        }
    };

    // ============================================
    // AUTO SOLVER
    // ============================================
    const AutoSolver = (function () {
        const RUNNING_KEY = 'leetcode_autosolver_running';
        const SKIP_KEY = 'leetcode_autosolver_skipped';
        const SOLVED_KEY = 'leetcode_autosolver_solved';
        const PANEL_ID = 'leetcode-autosolver-panel';
        const LIST_PANEL_ID = 'leetcode-autosolver-list-panel';

        let busy = false;
        let panel = null;
        let listPanel = null;
        let statusEl = null;
        let dotEl = null;
        let autoButton = null;
        let submitButton = null;
        let clearButton = null;
        let listStatusEl = null;

        const loadMap = (key) => {
            try { return JSON.parse(localStorage.getItem(key) || '{}') || {}; } catch (error) { return {}; }
        };
        const saveMap = (key, value) => {
            try { localStorage.setItem(key, JSON.stringify(value)); } catch (error) { /* ignore */ }
        };
        const loadSkipped = () => loadMap(SKIP_KEY);
        const loadSolved = () => loadMap(SOLVED_KEY);
        const isSkipped = (slug) => !!(slug && loadSkipped()[slug]);
        const isSolved = (slug) => !!(slug && loadSolved()[slug]);
        const markSkipped = (slug, title, reason) => {
            if (!slug) return;
            const map = loadSkipped();
            map[slug] = { title: title || '', reason: reason || 'failed', ts: Date.now() };
            saveMap(SKIP_KEY, map);
        };
        const markSolved = (slug) => {
            if (!slug) return;
            const map = loadSolved();
            map[slug] = { ts: Date.now() };
            saveMap(SOLVED_KEY, map);
        };
        const clearSkipped = () => {
            saveMap(SKIP_KEY, {});
            try { localStorage.removeItem(SKIP_KEY); } catch (error) { /* ignore */ }
            refreshControls();
        };

        const isRunning = () => {
            try { return sessionStorage.getItem(RUNNING_KEY) === '1'; } catch (error) { return false; }
        };
        const setRunning = (value) => {
            try {
                if (value) sessionStorage.setItem(RUNNING_KEY, '1');
                else sessionStorage.removeItem(RUNNING_KEY);
            } catch (error) { /* ignore */ }
            refreshControls();
        };

        const buttonStyle = (background) => `padding:5px 8px;border:0;border-radius:5px;background:${background};color:#fff;font:600 11px system-ui,-apple-system,Segoe UI,sans-serif;cursor:pointer;white-space:nowrap;`;

        const updateStatus = (message, tone = 'info') => {
            const colors = { info: '#38bdf8', success: '#4ade80', warning: '#fbbf24', error: '#f87171' };
            if (statusEl) statusEl.textContent = message;
            if (dotEl) dotEl.style.background = colors[tone] || colors.info;
            console.log('[AutoSolver] ' + message);
        };

        const refreshControls = () => {
            if (autoButton) {
                autoButton.textContent = isRunning() ? 'Auto: ON' : 'Auto: OFF';
                autoButton.style.background = isRunning() ? '#16a34a' : '#475569';
            }
            if (submitButton) {
                submitButton.textContent = SETTINGS.autoSolverAutoSubmit ? 'Submit: ON' : 'Submit: OFF';
                submitButton.style.background = SETTINGS.autoSolverAutoSubmit ? '#2563eb' : '#475569';
            }
            if (clearButton) {
                const count = Object.keys(loadSkipped()).length;
                clearButton.textContent = `Clear skips (${count})`;
                clearButton.disabled = count === 0;
                clearButton.style.opacity = count === 0 ? '0.5' : '1';
            }
        };

        const ensurePanel = () => {
            if (!isProblemPage() || !document.body) return;
            if (document.getElementById(PANEL_ID)) {
                panel = document.getElementById(PANEL_ID);
                statusEl = panel.querySelector('[data-role="status"]');
                dotEl = panel.querySelector('[data-role="dot"]');
                autoButton = panel.querySelector('[data-action="auto"]');
                submitButton = panel.querySelector('[data-action="submit"]');
                clearButton = panel.querySelector('[data-action="clear"]');
                return;
            }

            panel = document.createElement('div');
            panel.id = PANEL_ID;
            panel.style.cssText = 'position:fixed;left:14px;bottom:14px;z-index:999998;width:260px;padding:10px 12px;border-radius:10px;background:rgba(15,23,42,.96);color:#e2e8f0;border:1px solid rgba(148,163,184,.25);box-shadow:0 10px 30px rgba(0,0,0,.35);font:12px/1.4 system-ui,-apple-system,Segoe UI,sans-serif;';
            panel.innerHTML = `
                <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:6px;">
                    <strong style="font-size:12px;letter-spacing:.2px;color:#f8fafc;">LeetCode Auto Solver</strong>
                    <span data-role="dot" style="width:8px;height:8px;border-radius:50%;background:#38bdf8;display:inline-block;flex:none;"></span>
                </div>
                <div data-role="status" style="min-height:34px;color:#cbd5e1;margin-bottom:8px;">Idle. Click Auto to generate and solve the current problem.</div>
                <div style="display:flex;gap:6px;flex-wrap:wrap;">
                    <button type="button" data-action="solve" style="${buttonStyle('#7c3aed')}">Solve now</button>
                    <button type="button" data-action="auto" style="${buttonStyle('#475569')}">Auto: OFF</button>
                    <button type="button" data-action="submit" style="${buttonStyle('#475569')}">Submit: OFF</button>
                    <button type="button" data-action="skip" style="${buttonStyle('#b45309')}">Skip</button>
                    <button type="button" data-action="clear" style="${buttonStyle('#475569')}">Clear skips</button>
                </div>
            `;
            document.body.appendChild(panel);

            statusEl = panel.querySelector('[data-role="status"]');
            dotEl = panel.querySelector('[data-role="dot"]');
            autoButton = panel.querySelector('[data-action="auto"]');
            submitButton = panel.querySelector('[data-action="submit"]');
            clearButton = panel.querySelector('[data-action="clear"]');

            panel.querySelector('[data-action="solve"]').addEventListener('click', () => {
                if (busy) { showToast('The auto solver is busy.', 'info', 2000); return; }
                busy = true;
                updateStatus('Generating a solution...', 'info');
                generateAISolution().then((code) => {
                    if (code) updateStatus('Solution inserted. Use Submit to judge it.', 'success');
                    else updateStatus('Generation failed. Check the toast for details.', 'error');
                    busy = false;
                });
            });

            autoButton.addEventListener('click', () => toggleAuto());
            submitButton.addEventListener('click', () => {
                SETTINGS.autoSolverAutoSubmit = !SETTINGS.autoSolverAutoSubmit;
                saveSettings(SETTINGS);
                refreshControls();
                updateStatus(SETTINGS.autoSolverAutoSubmit
                    ? 'Auto-submit is ON. A logged-in LeetCode session is required.'
                    : 'Auto-submit is OFF. The solver will insert code only.', 'info');
            });
            clearButton.addEventListener('click', () => {
                clearSkipped();
                updateStatus('Skip list cleared.', 'success');
            });
            panel.querySelector('[data-action="skip"]').addEventListener('click', () => skipCurrent());

            refreshControls();
        };

        const removePanel = () => {
            if (panel) panel.remove();
            panel = null;
            statusEl = null;
            dotEl = null;
            autoButton = null;
            submitButton = null;
            clearButton = null;
        };

        const ensureListPanel = () => {
            if (!isProblemSetPage() || !document.body) return;
            if (document.getElementById(LIST_PANEL_ID)) {
                listPanel = document.getElementById(LIST_PANEL_ID);
                listStatusEl = listPanel.querySelector('[data-role="list-status"]');
                return;
            }

            listPanel = document.createElement('div');
            listPanel.id = LIST_PANEL_ID;
            listPanel.style.cssText = 'position:fixed;left:14px;bottom:14px;z-index:999998;width:250px;padding:10px 12px;border-radius:10px;background:rgba(15,23,42,.96);color:#e2e8f0;border:1px solid rgba(148,163,184,.25);box-shadow:0 10px 30px rgba(0,0,0,.35);font:12px/1.4 system-ui,-apple-system,Segoe UI,sans-serif;';
            listPanel.innerHTML = `
                <div style="font-weight:700;color:#f8fafc;margin-bottom:6px;">LeetCode Auto Solver</div>
                <div data-role="list-status" style="color:#cbd5e1;margin-bottom:8px;">Scan the problem list and start from the first non-skipped problem.</div>
                <button type="button" data-action="start-list" style="${buttonStyle('#7c3aed')}">Auto solve from list</button>
            `;
            document.body.appendChild(listPanel);
            listStatusEl = listPanel.querySelector('[data-role="list-status"]');
            listPanel.querySelector('[data-action="start-list"]').addEventListener('click', () => startFromList());
        };

        const removeListPanel = () => {
            if (listPanel) listPanel.remove();
            listPanel = null;
            listStatusEl = null;
        };

        const getListProblems = () => {
            const seen = new Set();
            return qsa('a[href*="/problems/"]')
                .map((anchor) => {
                    const href = anchor.getAttribute('href') || '';
                    const slug = (href.match(/\/problems\/([^/?#]+)/) || [])[1] || '';
                    const row = anchor.closest('[role="row"]') || anchor.closest('tr') || anchor.closest('div');
                    return {
                        slug,
                        href: slug ? `/problems/${slug}/` : href,
                        text: (anchor.innerText || '').trim(),
                        rowText: row ? (row.innerText || '') : '',
                        row,
                    };
                })
                .filter((item) => {
                    if (!item.slug || seen.has(item.slug)) return false;
                    seen.add(item.slug);
                    if (!/\d+\s*\./.test(item.rowText || item.text)) return false;
                    if (isSkipped(item.slug) || isSolved(item.slug)) return false;
                    return true;
                });
        };

        const startFromList = () => {
            const problems = getListProblems();
            if (!problems.length) {
                if (listStatusEl) listStatusEl.textContent = 'No problem rows found. Make sure the problem list has loaded.';
                showToast('No problem rows found on this page.', 'warning');
                return;
            }
            const next = problems[0];
            setRunning(true);
            if (listStatusEl) listStatusEl.textContent = `Opening ${next.text || next.slug}...`;
            showToast(`Opening ${next.text || next.slug}...`, 'info', 3000);
            location.assign(new URL(next.href, location.origin).href);
        };

        const waitForEditor = async (timeout) => {
            const model = await waitForEditorModel(timeout);
            return !!(model && typeof model.getValue === 'function' && model.getValue().length > 0);
        };

        const waitForResult = async (timeout) => {
            const start = Date.now();
            while (Date.now() - start < timeout) {
                const text = document.body ? (document.body.innerText || '') : '';
                if (/You need to log in|log in \/ sign up to run or submit/i.test(text)) {
                    return { type: 'login' };
                }
                const failure = text.match(/Wrong Answer|Runtime Error|Compile Error|Time Limit Exceeded|Memory Limit Exceeded|Output Limit Exceeded/);
                if (failure) return { type: 'failed', message: failure[0] };
                if (/\bAccepted\b/.test(text)) return { type: 'success', message: 'Accepted' };
                await wait(500);
            }
            return { type: 'unknown' };
        };

        const nextProblemHref = () => {
            const candidates = [
                qs('[data-e2e-locator="nav-next"]'),
                qs('a[aria-label="Next problem"]'),
                qs('a[rel="next"]'),
            ].filter(Boolean);

            for (const candidate of candidates) {
                const href = candidate.getAttribute('href');
                if (href) return href;
                const anchor = candidate.querySelector('a[href*="/problems/"]');
                if (anchor) return anchor.getAttribute('href');
            }
            return null;
        };

        const goNextProblem = () => {
            const href = nextProblemHref();
            if (!href) {
                updateStatus('No next-problem link found. Stopping.', 'warning');
                setRunning(false);
                return false;
            }
            updateStatus('Moving to the next problem...', 'info');
            location.assign(new URL(href, location.origin).href);
            return true;
        };

        const runCode = async () => {
            const submitBtn = qs('[data-e2e-locator="console-submit-button"]');
            const runBtn = qs('[data-e2e-locator="console-run-button"]');
            const button = submitBtn || runBtn;
            if (!button) return { type: 'error', message: 'Run/Submit button not found' };
            button.click();
            updateStatus('Waiting for the LeetCode judge...', 'info');
            return waitForResult(60000);
        };

        const skipCurrent = async () => {
            const context = getProblemContext();
            if (context.slug) markSkipped(context.slug, context.title, 'manual skip');
            updateStatus('Added to the skip list.', 'warning');
            refreshControls();
            goNextProblem();
        };

        const runAuto = async () => {
            if (busy) return;
            if (!isProblemPage()) {
                updateStatus('Open a LeetCode problem to start.', 'warning');
                return;
            }

            busy = true;
            refreshControls();
            let attempts = 0;
            const maxAttempts = Math.max(1, Number(SETTINGS.autoSolverMaxRetries) || 2);
            let feedback = '';

            try {
                if (!hasProblemUi()) {
                    updateStatus('Waiting for the problem page to load...', 'info');
                    for (let i = 0; i < 30 && !hasProblemUi(); i++) await wait(500);
                    if (!hasProblemUi()) throw new Error('LeetCode did not finish loading (possible Cloudflare challenge).');
                }
                while (isRunning()) {
                    updateStatus('Waiting for the code editor...', 'info');
                    const ready = await waitForEditor(25000);
                    if (!ready) throw new Error('The LeetCode editor did not load.');

                    const editorCode = readEditorCode();
                    const canReuse = attempts === 0 && !feedback && lastInjectedSolution && editorCode === lastInjectedSolution;
                    let code = editorCode;
                    if (canReuse) {
                        updateStatus('Using the solution already inserted in the editor...', 'info');
                    } else {
                        updateStatus(`Generating solution (attempt ${attempts + 1}/${maxAttempts})...`, 'info');
                        code = await generateAISolution({ auto: true, feedback });
                    }
                    if (!code) throw new Error('AI generation failed. Check the AI connection.');

                    if (!SETTINGS.autoSolverAutoSubmit) {
                        updateStatus('Solution inserted. Enable Submit to automate judging.', 'success');
                        setRunning(false);
                        return;
                    }

                    const result = await runCode();

                    if (result.type === 'login') {
                        updateStatus('Log in to LeetCode to run or submit automatically.', 'warning');
                        showToast('Auto-submit needs a logged-in LeetCode session.', 'warning', 6000);
                        setRunning(false);
                        return;
                    }

                    if (result.type === 'success') {
                        const context = getProblemContext();
                        markSolved(context.slug);
                        updateStatus('Accepted. Moving to the next problem...', 'success');
                        await wait(1500);
                        goNextProblem();
                        return;
                    }

                    if (result.type === 'unknown' || result.type === 'error') {
                        updateStatus(result.message || 'The judge did not report a result.', 'warning');
                        setRunning(false);
                        return;
                    }

                    attempts++;
                    feedback = result.message || 'failed';
                    if (attempts >= maxAttempts) {
                        const context = getProblemContext();
                        markSkipped(context.slug, context.title, feedback);
                        updateStatus(`Skipped after ${attempts} attempts (${feedback}).`, 'warning');
                        await wait(900);
                        goNextProblem();
                        return;
                    }

                    updateStatus(`Attempt failed (${feedback}). Retrying...`, 'warning');
                    await wait(1200);
                }
            } catch (error) {
                console.error('[AutoSolver]', error);
                updateStatus(`Stopped: ${error.message}`, 'error');
                showToast(`Auto solver stopped: ${error.message}`, 'error', 7000);
                setRunning(false);
            } finally {
                busy = false;
                refreshControls();
            }
        };

        const toggleAuto = () => {
            if (isRunning()) {
                setRunning(false);
                updateStatus('Stopped by user.', 'warning');
                return;
            }
            setRunning(true);
            updateStatus('Starting auto solver...', 'info');
            runAuto();
        };

        const refreshUI = () => {
            if (isProblemPage() && hasProblemUi()) {
                ensurePanel();
                refreshControls();
                removeListPanel();
            } else if (isProblemSetPage()) {
                ensureListPanel();
                removePanel();
            } else {
                removePanel();
                removeListPanel();
            }
        };

        const handleRouteChange = () => {
            refreshUI();
            if (isProblemPage() && hasProblemUi() && isRunning() && !busy) {
                setTimeout(runAuto, 1200);
            }
        };

        const init = () => {
            refreshUI();
            if (isProblemPage() && isRunning()) {
                setTimeout(runAuto, 1500);
            }
        };

        return {
            init,
            handleRouteChange,
            refreshUI,
            toggle: toggleAuto,
            start: () => { setRunning(true); runAuto(); },
            stop: () => { setRunning(false); updateStatus('Stopped by user.', 'warning'); },
            isRunning,
            skipCurrent,
            clearSkipped,
            updateStatus,
        };
    })();

    // ============================================
    // INITIALISATION & REACT RERENDER WATCHERS
    // ============================================
    const startLeetCodeUI = () => {
        ensureAISolutionButton();
        AutoSolver.init();

        let scheduled = false;
        const scheduleRefresh = () => {
            if (scheduled) return;
            scheduled = true;
            setTimeout(() => {
                scheduled = false;
                ensureAISolutionButton();
                AutoSolver.refreshUI();
            }, 350);
        };

        if (document.body) {
            new MutationObserver(scheduleRefresh).observe(document.body, { childList: true, subtree: true });
        }

        // LeetCode is a SPA; keep the button alive across client-side navigation.
        let lastUrl = location.pathname + location.search;
        setInterval(() => {
            const current = location.pathname + location.search;
            if (current !== lastUrl) {
                lastUrl = current;
                ensureAISolutionButton();
                AutoSolver.handleRouteChange();
            }
        }, 700);

        // Final safety net for React re-renders that replace the toolbar.
        setInterval(ensureAISolutionButton, 2500);
        window.addEventListener('popstate', scheduleRefresh);
    };

    onScriptEnabled(() => {
        if (document.body) startLeetCodeUI();
        else document.addEventListener('DOMContentLoaded', startLeetCodeUI, { once: true });
    });

    // ============================================
    // GLOBAL EXPOSURE (debugging / console use)
    // ============================================
    window.LeetCodeAI = {
        generate: generateAISolution,
        setEditorCode,
        readEditorCode,
        getProblemContext,
        getSelectedLanguage,
        settings: SETTINGS,
        saveSettings,
    };
    window.LeetCodeAutoSolver = AutoSolver;

    // Make the debug API available in the page console as well.
    try {
        pageWindow.LeetCodeAI = window.LeetCodeAI;
        pageWindow.LeetCodeAutoSolver = AutoSolver;
    } catch (error) { /* ignore */ }
})();

