                <input type="range" id="ets-fontSize" min="16" max="80" value="${config.fontSize}">

                <label>字体粗细</label>
                <select id="ets-fontWeight">
                    <option value="400">普通</option>
                    <option value="700">粗体</option>
                    <option value="900">特粗</option>
