    function normalizeColor(color, fallback) {
        if (typeof color !== "string") return fallback;
        const c = color.trim();
        if (/^#[0-9a-f]{6}$/i.test(c)) return c.toLowerCase() + "ff";
        if (/^#[0-9a-f]{8}$/i.test(c)) return c.toLowerCase();
        if (/^#[0-9a-f]{3}$/i.test(c)) {
