                    return h.length === 1 ? "0" + h : h;
                };
                const a = p.length > 3 ? Math.round(p[3] * 255) : 255;
                return "#" + hex(p[0]) + hex(p[1]) + hex(p[2]) + hex(a);
            }
        } catch (e) {}
