        try {
            const parts = lunarFmt.formatToParts(date);
            let month = "", day = "", hasYearName = false;
            for (let i = 0; i < parts.length; i++) {
                if (parts[i].type === "month") month = parts[i].value;
                else if (parts[i].type === "day") day = parts[i].value;
