                border-radius: 12px;
                width: 90%;
                max-width: 620px;
                box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.3);
                overflow: hidden;
                display: flex;
                flex-direction: column;
                color: ${CONFIG.MODAL_THEME.textColor};
                animation: slideUp 0.2s cubic-bezier(0.16, 1, 0.3, 1);
            }
            .modal-header {
                padding: 16px 20px;
