            border: 1px solid #45475a;
            border-radius: 10px;
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.4), 0 0 1px rgba(255, 255, 255, 0.1);
            font-size: 12px;
            line-height: 1.4;
            box-sizing: border-box;
