        }
        .url {
            font-size: 10px;
            color: #a6adc8;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }
        .body {
            font-size: 12px;
            color: #bac2de;
            overflow-y: auto;
            max-height: 130px;
            word-break: break-word;
        }
        .loader {
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 12px 0;
        }
        .spinner {
            width: 18px;
            height: 18px;
            border: 2px solid rgba(137, 180, 250, 0.2);
            border-top-color: #89b4fa;
            border-radius: 50%;
            animation: spin 0.8s linear infinite;
        }
        @keyframes spin {
            to { transform: rotate(360deg); }
        }
        .error-state {
