            if (saveOnStartup) {
                saveSearchRule({
                    target: targetUrl,
                    type: isRegexMode ? 'regex' : 'text',
                    pattern: searchValue,
                    replacement: replaceValue,
                    caseSensitive: isCaseSensitive
