      var midBefore = !!prv && /[A-Za-z]$/.test(prv);
      // 两侧都得是中文语境：否则英文句子里的 <a>contact us</a> 会被单独翻成半中半英
      var prevCN = !!prv && /[\u3400-\u9fff][，。：；、）]?$/.test(prv);
