    return true;
  }

  /** 中文语境下的标点本地化：链接/按钮被单独包在元素里时，紧跟的 "." "," 常常是独立文本节点 */
  var PUNCT = { ".": "。", ",": "，", ";": "；", ":": "：", "?": "？", "!": "！", ")": "）", "(": "（" };
  function localizePunct(node, text) {
    if (site.punctFix === false) return;
    if (!text || text.length > 2) return;
    // 复数后缀：站点把 " result" + "s" 拆成两个节点做 i18n，中文里不需要这个 s
    var raw = String(text || "").trim();
    if (raw === "s" || raw === "es") {
