    // <sup class="help_i">i</sup>，挡掉会把整类标签（Tissue specificity 等）留在英文。
    if (nsEl && nsEl.nodeType === 1 && /^(SUB|SUP)$/.test(nsEl.tagName) && /^[+\-]?[\d.]+$/.test(String(nsEl.textContent || "").trim())) { processed.add(node); return; }
