      // 即使词典里有 Contact Us，也不能在一句英文中间冒出一小块中文。
      if (text.length < 40 || lookupExact(text) === null) { recordMiss(text, node, true); return; }
    }

    stats.nodes++;
    // 按选择器精确替换优先：导航标签里的 Data/Tool 这类单词只在该元素里翻，
