    if (out !== null) stats.scoped = (stats.scoped || 0) + 1;
    if (out === null) out = translate(text);
    if (out === null) { recordMiss(text); processed.add(node); return; }

    // 首尾空白用下标扫描（原来是一条惰性量词正则，每个命中节点都跑一遍）
    var l0 = 0, l1 = raw.length;
