    // neighborChar 要读兄弟节点链，只有「本节点带着空白、且译文贴边是汉字」时才需要问
    if (lead && /^[\u3400-\u9fff（「【]/.test(out) && CN_PREV.test(neighborChar(node, -1))) lead = "";
