  // 站级 skip 与引擎同一语义：这些区块里的文字引擎根本不碰，漏翻清单也不该列
  // （cBioPortal 正文、GEO 的结果标题、miRBase 的分类树都是这一类）。
  var siteSkip = (opts.site && opts.site.skip) || "";
  var siteSkipFree = (opts.site && opts.site.skipFree) || [];
  var dict = opts.dict || {};
