  // ---------- 复制正文 / 收集漏翻 / 段落看原文（0.11.2） ----------
  var PAGE_SKIP = "script,style,noscript,template,svg,textarea,[data-biol10n-ui]";

  // ---------- 中英互查（选中即查 / 英文名定位 共用） ----------
  var revIndex = null;

  function normTerm(s) { return String(s || "").replace(/\s+/g, " ").trim(); }

  function lookupPair(term) {
    var t = normTerm(term);
    if (!t) return null;
    if (dict && Object.prototype.hasOwnProperty.call(dict, t)) return { en: t, zh: dict[t] };
    if (!revIndex) {
      revIndex = new Map();
      var ks = Object.keys(dict || {});
      for (var i = 0; i < ks.length; i++) {
        var v = dict[ks[i]];
        if (v && !revIndex.has(v)) revIndex.set(v, ks[i]);
      }
    }
    var en = revIndex.get(t);
    if (en) return { en: en, zh: t };
    // 选中的往往只是长句/长标签里的一段（如「数据提交」之于「数据提交门户」），
    // 精确匹配不到时退回包含匹配，优先取最短的那条词条。
    var best = null;
    var ks2 = Object.keys(dict || {});
    for (var j = 0; j < ks2.length; j++) {
      var k = ks2[j], v2 = dict[k];
      if (!v2) continue;
      if (v2.indexOf(t) >= 0 || k.toLowerCase().indexOf(t.toLowerCase()) >= 0) {
        if (!best || k.length < best.en.length) best = { en: k, zh: v2 };
      }
    }
    return best;
  }

  function visibleText() {
    var body = doc.body;
    if (!body) return "";
    var w = doc.createTreeWalker(body, 4, null, false), n, parts = [];
    while ((n = w.nextNode())) {
      var p = n.parentElement;
      if (p && p.closest && p.closest(PAGE_SKIP)) continue;
      parts.push(String(n.nodeValue || ""));
    }
    return parts.join("").replace(/[ \t\u00a0]+/g, " ").replace(/[ \t]*\n[ \t]*/g, "\n").trim();
  }

  /** 有选区就复制选区；否则整页（英文走引擎的原文拼装，不需要关脚本刷新）。 */
  function pickText(kind) {
    var sel = "";
    try { sel = String(win.getSelection ? win.getSelection().toString() : ""); } catch (e) {}
    if (sel && /\S/.test(sel)) return sel.trim();
    if (kind === "en" && engine && typeof engine.englishText === "function") {
      try {
        var t = engine.englishText();
        if (t) return t;
      } catch (e) {}
    }
    return visibleText();
  }

  function copyPayload(payload, okMsg) {
    if (!payload) { toast("没有可复制的内容"); return false; }
    // 页面没焦点时 navigator.clipboard.writeText 可能一直 pending（不 resolve 也不 reject），
    // 用户点了按钮却看不到任何反馈；900ms 后换 execCommand 兜底，保证一定有提示。
    var settled = false;
    var done = function () { if (settled) return; settled = true; toast(okMsg || "已复制"); };
    var fail = function () { if (settled) return; settled = true; toast("复制失败，请手动选中"); };
    var fallback = function () { if (settled) return; legacyCopy(payload) ? done() : fail(); };
    if (win.navigator && win.navigator.clipboard && win.navigator.clipboard.writeText) {
      win.setTimeout(fallback, 900);
      win.navigator.clipboard.writeText(payload).then(done, fallback);
    } else {
      fallback();
    }
    return true;
  }

  function copyKind(kind) {
    var t = pickText(kind);
    if (!t) { toast("这一页没有可复制的文字"); return ""; }
    copyPayload(t, (kind === "en" ? "已复制原文" : "已复制中文") + " " + t.length + " 字");
    return t;
  }

  var MISS_KEY = "biol10n:misses";

  function looksUntranslated(t) {
    if (!t || t.length < 3 || t.length > 90) return false;
    if (/[\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]/.test(t)) return false;
    if (/[：，。；！？、（）「」【】《》]/.test(t)) return false;   // 全角标点：已中文化或标识符
    if (!/[A-Za-z]{2}/.test(t)) return false;
    if (/^[\s\dA-Za-z._:/-]+$/.test(t) && !/ /.test(t)) return false;   // 纯编号/ID/文件名
    if (/@|https?:\/\/|www\./i.test(t)) return false;                  // 邮箱/URL
    return true;
  }

  /**
   * 站级噪音名单：流程名/工具名/品牌这类「本来就不翻」的词，不进漏翻清单。
   * 普通条目按子串匹配（大小写不敏感）；"re:" 开头的条目当正则用，作者自己加 ^ $ 决定整串还是前缀，
   * 用来覆盖登录号、基因组坐标、测序平台名这类成百上千的取值（枚举不完，但形状固定）。
   */
  var noiseRules = null;
  /** 名单只解析一次：blast 这类站点的正则条目有一千多字符，逐条 new RegExp 太贵。 */
  function noiseRuleSet() {
    if (noiseRules) return noiseRules;
    noiseRules = [];
    for (var i = 0; i < missNoise.length; i++) {
      var n = String(missNoise[i] || "").trim();
      if (!n) continue;
      var low = n.toLowerCase();
      // re: = 大小写不敏感正则；rec: = 大小写敏感正则（基因符号 A1BG 这类必须区分大小写，
      // 否则 "Search" 也会被 ^[A-Z][A-Z0-9]*$ 吃掉）。
      if (low.slice(0, 4) === "rec:") {
        try { noiseRules.push({ re: new RegExp(n.slice(4)), cs: true }); } catch (e) {}
      } else if (low.slice(0, 3) === "re:") {
        try { noiseRules.push({ re: new RegExp(n.slice(3), "i") }); } catch (e) {}
      } else {
        noiseRules.push({ sub: low });
      }
    }
    return noiseRules;
  }
  function isNoise(t) {
    var rules = noiseRuleSet();
    if (!rules.length) return false;
    var raw = String(t).trim();
    var s = raw.toLowerCase();
    for (var i = 0; i < rules.length; i++) {
      var r = rules[i];
      // rec: 的正则必须拿原串比：先把输入转小写，^[A-Z] 这类模式永远匹配不上
      if (r.re) { if (r.re.test(r.cs ? raw : s)) return true; }
      else if (s.indexOf(r.sub) >= 0) return true;
    }
    return false;
  }

  /** 扫本页仍是英文的短句（跳过代码块、UI 自身与站级噪音名单）；返回去重后的条目。 */
  function collectMisses() {
    var body = doc.body;
    if (!body) return [];
    var SKIP = "script,style,noscript,template,svg,pre,code,kbd,samp,textarea,[data-biol10n-ui]";
    var out = [], seen = Object.create(null);
    var w = doc.createTreeWalker(body, 4, null, false), n;
    while ((n = w.nextNode())) {
      var p = n.parentElement;
      if (!p || (p.closest && p.closest(SKIP))) continue;
      if (siteSkip && p.closest) {
        var skipped = false;
        try { skipped = !!p.closest(siteSkip); } catch (e2) { skipped = false; }
        if (skipped) {
          for (var fi = 0; fi < siteSkipFree.length; fi++) {
            try { if (p.closest(siteSkipFree[fi])) { skipped = false; break; } } catch (e3) {}
          }
        }
        if (skipped) continue;
      }
      var t = String(n.nodeValue || "").replace(/\s+/g, " ").trim();
      if (!looksUntranslated(t) || seen[t] || isNoise(t)) continue;
      try {
        var cs = win.getComputedStyle(p);
        if (cs && (cs.display === "none" || cs.visibility === "hidden")) continue;
      } catch (e1) {}
      seen[t] = 1;
      var blk = p.closest("p,li,td,th,dd,dt,div,section,article,h1,h2,h3,h4,h5,h6,label,button,a,figcaption,caption");
      var cls = blk && typeof blk.className === "string" ? blk.className.split(/\s+/)[0] : "";
      out.push({
        t: t,
        host: win.location.hostname || "",
        p: win.location.pathname || "/",
        tag: p.tagName.toLowerCase(),
        at: blk ? blk.tagName.toLowerCase() + (cls ? "." + cls : "") : ""
      });
      if (out.length >= 200) break;
    }
    return out;
  }

  function saveMisses(list) {
    var all = [];
    try {
      var raw = win.localStorage.getItem(MISS_KEY);
      all = raw ? JSON.parse(raw) : [];
    } catch (e) { all = []; }
    if (!Array.isArray(all)) all = [];
    var key = Object.create(null);
    all.forEach(function (x) { if (x && x.t) key[x.host + "\u0001" + x.p + "\u0001" + x.t] = 1; });
    var added = 0;
    list.forEach(function (x) {
      var k = x.host + "\u0001" + x.p + "\u0001" + x.t;
      if (key[k]) return;
      key[k] = 1;
      all.push({ t: x.t, host: x.host, p: x.p, tag: x.tag, at: x.at, ts: Date.now() });
      added++;
    });
    if (all.length > 800) all = all.slice(-800);
    try { win.localStorage.setItem(MISS_KEY, JSON.stringify(all)); } catch (e2) {}
    return { added: added, total: all.length, all: all };
  }

  function reportMisses() {
    var list = collectMisses();
    var res = saveMisses(list);
    var payload = list.map(function (x) { return x.t + "\t" + x.host + x.p.replace(/\/$/, "") + (x.at ? "\t" + x.at : ""); }).join("\n");
    if (!list.length) {
      toast("本页没扫到明显漏翻（累计已记 " + res.total + " 条）");
      return { found: 0, added: 0, total: res.total, list: list };
    }
    copyPayload(payload, "本页 " + list.length + " 条，新记 " + res.added + " 条（累计 " + res.total + "），已复制");
    return { found: list.length, added: res.added, total: res.total, list: list };
  }

  // ---------- 段落看原文：按住 Alt 点段落，弹出英文原文卡片 ----------
  var cardEl = null;

  function hideCard() {
    if (cardEl) { try { cardEl.remove(); } catch (e) {} cardEl = null; }
  }

  function showCard(text, x, y) {
    hideCard();
    cardEl = el("div", "bl-card");
    cardEl.setAttribute("data-biol10n-ui", "1");
    cardEl.setAttribute("role", "dialog");
    var hd = el("div", "bl-card-hd");
    hd.appendChild(el("span", null, "英文原文"));
    var x2 = el("button", "bl-card-x", "\u00d7");
    x2.type = "button";
    x2.title = "关闭（Esc）";
    x2.addEventListener("click", hideCard);
    hd.appendChild(x2);
    cardEl.appendChild(hd);
    cardEl.appendChild(el("div", "bl-card-bd", text));
    var btns = el("div", "bl-btns");
    var c1 = el("button", "bl-btn", "复制英文");
    c1.type = "button";
    c1.addEventListener("click", function () { copyPayload(text, "已复制英文"); });
    btns.appendChild(c1);
    cardEl.appendChild(btns);
    (doc.body || doc.documentElement).appendChild(cardEl);
    var w = cardEl.offsetWidth || 360, h = cardEl.offsetHeight || 200;
    var left = Math.max(6, Math.min(win.innerWidth - w - 6, (x || 12) - 24));
    var top = (y || 12) + 16;
    if (top + h > win.innerHeight - 8) top = Math.max(6, (y || 12) - h - 16);
    cardEl.style.left = Math.round(left) + "px";
    cardEl.style.top = Math.round(top) + "px";
  }

  function onAltClick(e) {
    if (!settings.paraOrig || !e.altKey || !engine) return;
    var t = e.target;
    if (!t || !t.closest || t.closest("[data-biol10n-ui]")) return;
    if (engine.stats && engine.stats.enabled === false) { toast("当前显示的就是原文"); return; }
    var blk = t.closest("p,li,td,th,dd,dt,div,section,article,h1,h2,h3,h4,h5,h6,figcaption,caption,label,blockquote,summary");
    if (!blk) return;
    var orig = null;
    try { orig = engine.originalText(blk); } catch (e1) {}
    if (!orig) {
      var cur = blk.parentElement, hops = 0;
      while (cur && hops < 4 && !orig) {
        try { orig = engine.originalText(cur); } catch (e2) {}
        cur = cur.parentElement;
        hops++;
      }
    }
    var now = (blk.textContent || "").replace(/\s+/g, " ").trim();
    if (!orig || orig === now) { toast("这段没有可还原的原文"); return; }
    e.preventDefault();
    e.stopPropagation();
    // 原文常带缩进/换行（HTML 里的制表符与换行），卡片里折成单行更好读
    showCard(String(orig).replace(/\s+/g, " ").trim(), e.clientX, e.clientY);
  }


  // ---------- 选中即查：选中中文/英文，浮出中英对照（0.12.0） ----------
  var selPop = null;

  function hideSel() {
    if (selPop) { try { selPop.remove(); } catch (e) {} selPop = null; }
  }

  function showSel(pair, x, y) {
    hideSel();
    selPop = el("div", "bl-sel");
    selPop.setAttribute("data-biol10n-ui", "1");
    var r1 = el("div", null);
    r1.appendChild(el("span", "bl-sel-k", "英文 "));
    r1.appendChild(el("b", null, pair.en));
    selPop.appendChild(r1);
    var r2 = el("div", null);
    r2.appendChild(el("span", "bl-sel-k", "中文 "));
    r2.appendChild(el("b", null, pair.zh));
    selPop.appendChild(r2);
    selPop.appendChild(el("div", "bl-sel-k", "点击复制中英对照"));
    selPop.addEventListener("click", function () { copyPayload(pair.zh + "\t" + pair.en, "已复制中英对照"); hideSel(); });
    (doc.body || doc.documentElement).appendChild(selPop);
    var w = selPop.offsetWidth || 240, h = selPop.offsetHeight || 70;
    selPop.style.left = Math.max(6, Math.min(win.innerWidth - w - 6, (x || 12))) + "px";
    selPop.style.top = Math.max(6, Math.min(win.innerHeight - h - 6, (y || 12) + 16)) + "px";
  }

  function onSelect(e) {
    if (e && e.target && e.target.closest && e.target.closest("[data-biol10n-ui]")) return;
    win.setTimeout(function () {
      var s = "";
      try { s = String(win.getSelection ? win.getSelection().toString() : ""); } catch (err) {}
      s = normTerm(s);
      if (!s || s.length > 60 || s.indexOf("\n") >= 0) { hideSel(); return; }
      var pair = lookupPair(s);
      if (!pair) { hideSel(); return; }
      showSel(pair, e.clientX, e.clientY);
    }, 30);
  }

  // ---------- 按英文名找控件（教程里点名的按钮） ----------
  var findList = [], findIdx = -1, findInput = null, findHint = null;

  function clearHits() {
    for (var i = 0; i < findList.length; i++) {
      var h = findList[i];
      if (h && h.classList) { h.classList.remove("bl-hit"); h.classList.remove("bl-hit-cur"); }
    }
    findList = [];
    findIdx = -1;
  }

  function findEnglish(q) {
    clearHits();
    q = normTerm(q).toLowerCase();
    if (!q || !engine) return 0;
    var cands = doc.body ? doc.body.querySelectorAll("a,button,label,th,td,li,h1,h2,h3,h4,h5,h6,span,div,option,p,summary") : [];
    var out = [];
    for (var i = 0; i < cands.length && out.length < 400; i++) {
      var e = cands[i];
      if (e.closest && e.closest("[data-biol10n-ui]")) continue;
      var orig = null;
      try { orig = engine.originalText(e); } catch (err) {}
      if (!orig) continue;
      var o = normTerm(orig).toLowerCase();
      if (!o || o.indexOf(q) < 0) continue;
      out.push(e);
    }
    // 父子同时命中时只留后代，避免一个容器和它里面的按钮同时高亮
    findList = out.filter(function (e) {
      return !out.some(function (x) { return x !== e && e.contains && e.contains(x); });
    }).slice(0, 80);
    for (var j = 0; j < findList.length; j++) if (findList[j].classList) findList[j].classList.add("bl-hit");
    findIdx = findList.length ? 0 : -1;
    if (findIdx >= 0) scrollHit();
    return findList.length;
  }

  function scrollHit() {
    if (findIdx < 0 || !findList[findIdx]) return;
    var target = findList[findIdx];
    for (var i = 0; i < findList.length; i++) if (findList[i].classList && findList[i] !== target) findList[i].classList.remove("bl-hit-cur");
    if (target.classList) target.classList.add("bl-hit-cur");
    try { target.scrollIntoView({ block: "center", behavior: "smooth" }); } catch (e) { try { target.scrollIntoView(); } catch (e2) {} }
    if (findHint) findHint.textContent = "第 " + (findIdx + 1) + " / " + findList.length + " 个匹配";
  }

  function nextHit() {
    if (!findList.length) { if (findHint) findHint.textContent = "先输入英文名再定位"; return; }
    findIdx = (findIdx + 1) % findList.length;
    scrollHit();
  }

  function runFind() {
    if (!findInput) return 0;
    var n = findEnglish(findInput.value);
    if (findHint) findHint.textContent = n ? "找到 " + n + " 个匹配，按「下一个」逐个跳" : "没找到：试试更短的英文或控件全名";
    return n;
  }

  // ---------- 双语对照（中文段落下方灰字原文） ----------
  var DUAL_SEL = "p,li,dd,dt,td,th,caption,figcaption,blockquote,h1,h2,h3,h4";
  var dualDone = new WeakSet();

  function removeDual() {
    var nodes = doc.querySelectorAll(".bl-dual");
    for (var i = 0; i < nodes.length; i++) nodes[i].remove();
    dualDone = new WeakSet();
  }

  function applyDual() {
    if (!settings.dual || !engine || (engine.stats && engine.stats.enabled === false)) { removeDual(); return 0; }
    var els = doc.body ? doc.body.querySelectorAll(DUAL_SEL) : [];
    var added = 0;
    for (var i = 0; i < els.length && i < 4000; i++) {
      var e = els[i];
      if (e.closest && e.closest("[data-biol10n-ui]")) continue;
      // 导航/页眉/页脚里的短链接不适合逐条加原文，会把菜单撑乱
      if (e.closest && e.closest("nav,header,footer,.md-nav,.md-sidebar,.md-header,.toc,.navbar")) continue;
      if (dualDone.has(e)) continue;
      var orig = null;
      try { orig = engine.originalText(e); } catch (err) {}
      if (!orig) continue;
      var now = normTerm(e.textContent);
      orig = normTerm(orig);
      var minLen = (e.tagName === "LI" || e.tagName === "TD" || e.tagName === "TH") ? 40 : 12;
      if (!orig || orig === now || orig.length < minLen || !/[A-Za-z]{3}/.test(orig)) continue;
      var line = el("div", "bl-dual", orig.length > 420 ? orig.slice(0, 420) + "…" : orig);
      line.setAttribute("data-biol10n-ui", "1");
      line.setAttribute("data-bl-dual", "1");
      e.appendChild(line);
      dualDone.add(e);
      added++;
    }
    return added;
  }

  // ---------- 记住阅读位置 ----------
  var SCROLL_KEY = "biol10n:scroll";

  function scrollStore() {
    try { return JSON.parse(win.localStorage.getItem(SCROLL_KEY) || "{}") || {}; } catch (e) { return {}; }
  }

  function saveScroll() {
    if (!settings.scrollMem) return;
    var y = win.pageYOffset || win.scrollY || 0;
    if (y < 200) return;
    var o = scrollStore();
    var k = (win.location.pathname || "/") + (win.location.search || "");
    o[k] = { y: Math.round(y), t: Date.now() };
    var keys = Object.keys(o);
    if (keys.length > 80) {
      keys.sort(function (a, b) { return (o[a].t || 0) - (o[b].t || 0); });
      keys.slice(0, keys.length - 80).forEach(function (x) { delete o[x]; });
    }
    try { win.localStorage.setItem(SCROLL_KEY, JSON.stringify(o)); } catch (e1) {}
  }

  function restoreScroll(immediate) {
    if (!settings.scrollMem) return 0;
    var o = scrollStore();
    var k = (win.location.pathname || "/") + (win.location.search || "");
    var rec = o[k];
    if (!rec || !rec.y || rec.y < 400) return 0;
    if (immediate) {
      try { win.scrollTo(0, rec.y); } catch (e) {}
      return rec.y;
    }
    // 首次 1.2s 时页面可能还没铺开，scrollTo 会被文档高度夹短；隔一会儿再补两次。
    // 只有在「我们还没动过、用户也没动过」时才抢滚动，之后只补夹短的差额。
    var tries = 0, did = false;
    var attempt = function () {
      var cur = win.pageYOffset || win.scrollY || 0;
      if (!did && cur > 40) return;   // 用户自己先滚了，不再抢
      try { win.scrollTo(0, rec.y); } catch (e) {}
      did = true;
      tries++;
      if (tries < 4 && (win.pageYOffset || win.scrollY || 0) < rec.y - 60) win.setTimeout(attempt, 1600);
    };
    win.setTimeout(attempt, 1200);
    return rec.y;
  }

  function updateTitle() {
    if (!badge) return;
    var s = statLine();
    var on = !engine || !engine.stats || engine.stats.enabled !== false;
    badge.className = "bl-badge" + (on ? "" : " bl-off");
    var mark = on ? "中" : "英";
    if (badge.textContent !== mark) badge.textContent = mark;
    // 计数要按通道求和：RCSB/GTEx 这类页面大部分命中走规则与属性，
    // 只看 nodes 会让徽标长期显示 0（检查方反馈）。
    var total = (s.nodes || 0) + (s.attrHit || 0) + (s.titleHit || 0);
    var tip = "BioL10n" + (on ? "：本页已汉化 " + total + " 处" : "：本页已切回英文") +
      (settings.log ? " · 记录中（" + entries.length + " 条）" : "");
    if (badge.title !== tip) badge.title = tip;
  }

  function renderList() {
    if (!nodes.list) return;
    nodes.list.textContent = "";
    if (!entries.length) {
      nodes.list.appendChild(el("div", "bl-empty", settings.log ? "本页暂未发现漏翻文本" : "记录未开启（已发现漏翻 " + ((engine && engine.stats && engine.stats.miss) || 0) + " 条，开启后显示明细）"));
      return;
    }
    var frag = doc.createDocumentFragment();
    for (var i = entries.length - 1; i >= 0 && i >= entries.length - 120; i--) {
      var e = entries[i];
      var it = el("div", "bl-item", e.t);
      it.title = "点击复制：" + e.t;
      if (e.p && e.p !== "/") it.appendChild(el("span", "bl-p", e.p.length > 34 ? e.p.slice(0, 34) + "…" : e.p));
      (function (txt) {
        it.addEventListener("click", function () {
          if (win.navigator && win.navigator.clipboard && win.navigator && win.navigator.clipboard.writeText) win.navigator && win.navigator.clipboard.writeText(txt).then(function () { toast("已复制"); }, function () { legacyCopy(txt); toast("已复制"); });
          else { legacyCopy(txt); toast("已复制"); }
        });
      })(e.t);
      frag.appendChild(it);
    }
    nodes.list.appendChild(frag);
  }

  function refresh() {
    if (!panel || !settingsOpen) return;
    var s = statLine();
    nodes.site.textContent = (site.name || site.id || "本站") + (win.location.hostname ? "（" + win.location.hostname + "）" : "");
    nodes.dict.textContent = "";
    var chips = el("span", "bl-chips");
    if (dicts.length) {
      dicts.forEach(function (d) {
        chips.appendChild(el("span", "bl-chip", d.id + " " + d.count + " 条"));
      });
    } else {
      chips.appendChild(el("span", "bl-chip", "通用词库"));
    }
    nodes.dict.appendChild(chips);
    nodes.stats.textContent = "";
    var parts = [["已替换", s.nodes], ["整条命中", s.exact], ["规则命中", s.rule], ["整段", s.paras], ["模板", s.tpl], ["属性", s.attrs], ["漏翻", s.miss]];
    parts.forEach(function (p) {
      var d = el("span", null);
      d.appendChild(el("b", null, String(p[1])));
      d.appendChild(doc.createTextNode(" " + p[0]));
      nodes.stats.appendChild(d);
    });
    nodes.pauseBtn.textContent = (engine && engine.stats && engine.stats.enabled === false) ? "恢复汉化" : "暂停本页汉化";
    dirty = false;
    renderList();
    updateTitle();
  }

  function togglePanel(force) {
    var want = force === undefined ? !settingsOpen : !!force;
    if (want && !panel) buildPanel();
    settingsOpen = want;
    if (panel) panel.style.display = want ? "" : "none";
    if (want) refresh();
  }

  function onKey(e) {
    if (e.key === "Escape") {
      if (selPop) { hideSel(); return; }
      if (findList.length) { clearHits(); if (findHint) findHint.textContent = ""; return; }
      if (cardEl) { hideCard(); return; }
      if (settingsOpen) { togglePanel(false); return; }
      if (popOpen) { toggleQuick(false); return; }
    }
    if (e.altKey && e.shiftKey && (e.key === "B" || e.key === "b")) {
      settings.badge = !settings.badge;
      bioL10nSaveSettings(settings);
      if (badge) badge.style.display = settings.badge ? "" : "none";
      if (!settings.badge) togglePanel(false);
    }
  }

  function mount() {
    injectCSS();
    if (settings.badge) makeBadge();
    refreshState();
    applyContrast();
    doc.addEventListener("keydown", onKey, true);
    // 按住 Alt 点段落 = 就地看该段英文原文（不整页切换、不刷新）
    doc.addEventListener("click", onAltClick, true);
    // 选中即查：选中一段中文或英文，浮出中英对照
    doc.addEventListener("mouseup", onSelect, true);
    // 记住阅读位置：离开页面前存，进页面后恢复
    win.addEventListener("pagehide", saveScroll);
    win.addEventListener("beforeunload", saveScroll);
    doc.addEventListener("visibilitychange", function () { if (doc.visibilityState === "hidden") saveScroll(); });
    restoreScroll(false);
    // 点空白处收起快捷菜单、原文卡片与选中查询
    doc.addEventListener("pointerdown", function (e) {
      var t = e.target;
      if (selPop && !selPop.contains(t)) hideSel();
      if (cardEl && !cardEl.contains(t)) hideCard();
      if (!popOpen) return;
      if (t === badge || (pop && pop.contains(t)) || (badge && badge.contains(t))) return;
      toggleQuick(false);
    }, true);
    win.addEventListener("resize", function () { if (popOpen) positionPop(); });
    // 徽标/统计/面板都是活数据：每秒刷一次（只在文案变化时才写 DOM）
    win.setInterval(function () { refreshState(); if (settingsOpen) refresh(); }, 1000);
    // 双语对照要跟得上 SPA 新渲染的段落；没开启时这个定时器只做一次布尔判断
    win.setInterval(function () { if (settings.dual) applyDual(); }, 2500);
  }

  function attach(eng) {
    engine = eng;
    // 记住过「本站暂停」的站点，刷新后直接保持原文
    if (hostPaused() && langOn()) engine.disable();
    applyContrast();
    refreshState();
    if (settings.dual) applyDual();
    if (settingsOpen) refresh();
  }

  loadEntries();
  if (doc.body) mount();
  else doc.addEventListener("DOMContentLoaded", mount, { once: true });

  return {
    settings: settings,
    attach: attach,
    addMiss: addMiss,
    toggle: togglePanel,
    toggleLanguage: toggleLanguage,
    refreshState: refreshState,
    badge: function () { return badge; },
    panel: function () { return panel; },
    entries: function () { return entries.slice(); },
    // 0.11.2：复制与漏翻上报（暴露出来给单测与排查用）
    textOf: pickText,
    copyKind: copyKind,
    collectMisses: collectMisses,
    reportMisses: reportMisses,
    card: function () { return cardEl; },
    // 0.12.0：中英互查、英文名定位、双语对照、阅读位置
    lookupPair: lookupPair,
    findEnglish: findEnglish,
    nextHit: nextHit,
    applyDual: applyDual,
    removeDual: removeDual,
    saveScroll: saveScroll,
    restoreScroll: restoreScroll,
    selPair: function () { return selPop; },
    misses: function () {
      try { return JSON.parse(win.localStorage.getItem(MISS_KEY) || "[]"); } catch (e) { return []; }
    }
  };
}

