/**
 * XXX on website that use color function "oklch", html2canvas fail to capture screenshot.
 * Page screenshot failed: Error: Attempting to parse an unsupported color function "oklch".
 * MOVED to html2canvas-pro.
 */

/**
 * XXX Applying inline style violates the following Content Security Policy directive 'style-src 'self''. The action has been blocked.
 * Caused by html2canvas-pro.
 */

(function() {
'use strict';

// ==========================================
// CONFIGURATION & CONSTANTS
// ==========================================
const CONFIG = {
    // Default filename prefix for downloaded screenshots
    FILENAME_PREFIX: 'screenshot',

    // Highlight styling during element selection mode
    HIGHLIGHT_OUTLINE: '2px dashed #ff4757',
    HIGHLIGHT_BG: 'rgba(255, 71, 87, 0.15)',

    // Z-Index for modal and highlight overlay
    MODAL_Z_INDEX: 2147483647,

    // Custom options passed directly to html2canvas
    // Options reference: https://html2canvas.hertzen.com/configuration
    HTML2CANVAS_OPTIONS: {
        useCORS: true,
        allowTaint: false,
        logging: false,
        backgroundColor: '#ffffff',
        // Disable foreignObject rendering to prevent SVG data: URI CSP violations
        foreignObjectRendering: false
    }
};

// ==========================================
// STYLES INJECTION
// ==========================================

function adoptStyleSheet(target, cssText) {
    if (!cssText || !target || typeof CSSStyleSheet === 'undefined' || !('adoptedStyleSheets' in target)) {
        return;
    }

    try {
        const sheet = new CSSStyleSheet();
        sheet.replaceSync(cssText);
        const existingSheets = Array.from(target.adoptedStyleSheets || []);
        if (!existingSheets.some(existingSheet => existingSheet.cssText === sheet.cssText)) {
            target.adoptedStyleSheets = [...existingSheets, sheet];
        }
    } catch (err) {
        console.warn('[Screenshot] Failed to adopt stylesheet:', err);
    }
}

const STYLES = `
    .ts-modal-overlay {
        position: fixed;
        top: 0;
        left: 0;
        width: 100vw;
        height: 100vh;
        background: rgba(0, 0, 0, 0.7);
        z-index: ${CONFIG.MODAL_Z_INDEX};
        display: flex;
        align-items: center;
        justify-content: center;
        font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
        box-sizing: border-box;
    }

    .ts-modal-card {
        background: #ffffff;
        border-radius: 8px;
        width: 80vw;
        max-width: 900px;
        max-height: 85vh;
        display: flex;
        flex-direction: column;
        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
        overflow: hidden;
        animation: ts-fade-in 0.2s ease-out;
    }

    @keyframes ts-fade-in {
        from { opacity: 0; transform: scale(0.95); }
        to { opacity: 1; transform: scale(1); }
    }

    .ts-modal-header {
        padding: 14px 20px;
        background: #f8f9fa;
        border-bottom: 1px solid #e9ecef;
        display: flex;
        justify-content: space-between;
        align-items: center;
        font-weight: 600;
        font-size: 16px;
        color: #212529;
    }

    .ts-modal-body {
        padding: 20px;
        overflow: auto;
        max-height: calc(85vh - 120px);
