            currFull,
            currNoHash,
            currHost,
            currHostname,
            currHostPath,
            currHostnamePath,
            currProtoHost,
            currProtoHostname,
            currProtoHostPath,
            currProtoHostnamePath,
            currHostPathQuery,
            currHostnamePathQuery
        ];

        const stripTrailingSlash = str => str.replace(/\/+$/, '');

