      if (!canRepeat) {
        fail(rawMessage);
        return;
      }
      directHttpRequest(details)
        .then((result) => details.onload && details.onload(result))
        .catch((error) =>
          fail(`${friendlyExtensionError(rawMessage)}; direct fallback failed: ${error.message}`)
