// SourceCapsule native messaging host.
//
// Chrome spawns this process (never the other way around), so the CLI cannot talk to
// the extension directly. This host bridges the two:
//   CLI  --(newline JSON over a Windows named pipe)-->  host
//   host --(native messaging framing over stdio)------>  extension service worker
// and routes the reply back by request id.
//
// Exactly one host owns the pipe. A second instance cannot listen, stays attached to
// its browser, and retries every few seconds, so it takes over when the owner exits.
// The pending entry (one per in-flight capture) is what enforces one capture at a time.
'use strict';

import net from 'node:net';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

// Windows named pipe path: \\.\pipe\sourcecapsule-capture
const DEFAULT_PIPE = String.raw`\\.\pipe\sourcecapsule-capture`;
// Tests (and any parallel install) can point at their own pipe so they never fight
// the host the browser already has running.
const PIPE = process.env.SOURCECAPSULE_PIPE || DEFAULT_PIPE;
// Tests point this at their own file so fake replies never land in the log an owner
// reads to diagnose a live capture (#105).
const LOG =
  process.env.SOURCECAPSULE_HOST_LOG || path.join(os.tmpdir(), 'sourcecapsule-native-host.log');
const REQUEST_MAX_MS = 15 * 60 * 1000;
// After a request timeout the capture may still be running in the extension. Keep the
// lock this much longer, then give up so a dead worker cannot hold it forever.
const LOCK_GRACE_MS = Number(process.env.SOURCECAPSULE_LOCK_GRACE_MS) || 2 * 60 * 1000;
const LISTEN_RETRY_MS = Number(process.env.SOURCECAPSULE_LISTEN_RETRY_MS) || 3000;

function log(...parts) {
  const line = `${new Date().toISOString()} ${parts.join(' ')}\n`;
  try {
    fs.appendFileSync(LOG, line);
  } catch {
    /* logging must never take the host down */
  }
}

// ---- Chrome side: native messaging framing -------------------------------------

// Independently of the launcher, the host refuses to outlive its browser. An orphan
// keeps the named pipe, so every later CLI request reaches a host whose extension is
// gone and times out instead of failing fast. The 20s heartbeat means a dead stdout is
// noticed within 20s even when nothing else is happening.
function exitBecauseBrowserIsGone(reason) {
  log('browser connection gone:', reason, '- exiting so the pipe is released');
  process.exit(0);
}

function sendToChrome(message) {
  const body = Buffer.from(JSON.stringify(message), 'utf8');
  const header = Buffer.alloc(4);
  header.writeUInt32LE(body.length, 0);
  try {
    process.stdout.write(Buffer.concat([header, body]));
  } catch (error) {
    exitBecauseBrowserIsGone(`stdout write failed (${error.message})`);
  }
}

let stdinBuffer = Buffer.alloc(0);
function readChromeMessages(onMessage) {
  process.stdin.on('data', (chunk) => {
    stdinBuffer = Buffer.concat([stdinBuffer, chunk]);
    for (;;) {
      if (stdinBuffer.length < 4) return;
      const length = stdinBuffer.readUInt32LE(0);
      if (stdinBuffer.length < 4 + length) return;
      const body = stdinBuffer.subarray(4, 4 + length);
      stdinBuffer = stdinBuffer.subarray(4 + length);
      try {
        onMessage(JSON.parse(body.toString('utf8')));
      } catch (error) {
        log('bad message from chrome:', error.message);
      }
    }
  });
  // 'end' is the clean case. 'close' and 'error' cover a browser that was killed rather
  // than closed, which is how an orphan was surviving a Brave restart.
  process.stdin.on('end', () => exitBecauseBrowserIsGone('stdin ended'));
  process.stdin.on('close', () => exitBecauseBrowserIsGone('stdin closed'));
  process.stdin.on('error', (error) => exitBecauseBrowserIsGone(`stdin error (${error.message})`));
  process.stdout.on('error', (error) =>
    exitBecauseBrowserIsGone(`stdout error (${error.message})`)
  );
}

// ---- CLI side: named pipe -------------------------------------------------------

// id -> { socket, timer, cliGone }. An entry is the capture lock: it lives until the
// extension replies (or a hard cap after the request timer), NOT until the CLI socket
// closes or the request timer fires. The extension keeps capturing after the CLI walks
// away, and dropping the entry then let a second capture start on top of it and threw
// away the finished capsule's reply.
const pending = new Map();

function onRequestTimeout(id, timeoutMs) {
  const entry = pending.get(id);
  if (!entry) return;
  if (!entry.cliGone && !entry.socket.destroyed) {
    try {
      entry.socket.write(
        `${JSON.stringify({ ok: false, error: 'timeout', message: `No reply within ${timeoutMs}ms.` })}
`
      );
      entry.socket.end();
    } catch (error) {
      log('failed writing timeout reply', id, error.message);
    }
  }
  // Answer the CLI, keep the lock: the capture may still publish.
  entry.cliGone = true;
  entry.timer = setTimeout(() => {
    pending.delete(id);
    log('giving up on', id, `${LOCK_GRACE_MS}ms after its timeout; releasing the capture lock`);
  }, LOCK_GRACE_MS);
}

function replyToCli(id, payload) {
  const entry = pending.get(id);
  if (!entry) {
    // A capture the host already gave up on can still publish. Keep its link.
    const link = payload && payload.viewUrl ? ` viewUrl=${payload.viewUrl}` : '';
    log('reply for unknown or expired id', id, `ok=${!!(payload && payload.ok)}`, link);
    return;
  }
  clearTimeout(entry.timer);
  pending.delete(id);
  if (entry.cliGone || entry.socket.destroyed) {
    // Nobody to answer, but a published capsule must not vanish: keep its link in the log.
    const link = payload && payload.viewUrl ? ` viewUrl=${payload.viewUrl}` : '';
    log(
      'reply for',
      id,
      'arrived after the CLI disconnected;',
      `ok=${!!(payload && payload.ok)}`,
      link
    );
    return;
  }
  try {
    entry.socket.write(`${JSON.stringify(payload)}\n`);
    entry.socket.end();
  } catch (error) {
    log('failed writing reply', id, error.message);
  }
}

const server = net.createServer((socket) => {
  let buffer = '';
  socket.setEncoding('utf8');
  socket.on('close', () => {
    // Mark, never delete: the capture is still running and still owns the lock.
    for (const entry of pending.values()) {
      if (entry.socket === socket) entry.cliGone = true;
    }
  });
  socket.on('data', (chunk) => {
    buffer += chunk;
    let index;
    while ((index = buffer.indexOf('\n')) >= 0) {
      const line = buffer.slice(0, index);
      buffer = buffer.slice(index + 1);
      if (!line.trim()) continue;
      let request;
      try {
        request = JSON.parse(line);
      } catch {
        socket.write(`${JSON.stringify({ ok: false, error: 'invalid_json' })}\n`);
        socket.end();
        return;
      }
      const id = String(request.id || Date.now());
      if (pending.size > 0 && request.action !== 'ping') {
        socket.write(
          `${JSON.stringify({ ok: false, error: 'busy', message: 'Another SourceCapsule capture is already running.' })}
`
        );
        // End this socket only if it has no request of its own still in flight, so a
        // refusal can never cut off the capture it was refused because of.
        const ownsPending = [...pending.values()].some((entry) => entry.socket === socket);
        if (!ownsPending) socket.end();
        continue;
      }
      const timeoutMs = Math.min(Number(request.timeoutMs) || REQUEST_MAX_MS, REQUEST_MAX_MS);
      const timer = setTimeout(() => onRequestTimeout(id, timeoutMs), timeoutMs);
      pending.set(id, { socket, timer, cliGone: false });
      log('forwarding', id, request.action || 'unknown');
      sendToChrome({ ...request, id });
    }
  });
  socket.on('error', (error) => log('cli socket error:', error.message));
});

let listenRetry = null;
let reportedInUse = false;

function listen() {
  listenRetry = null;
  server.listen(PIPE);
}

server.on('error', (error) => {
  log('pipe listen failed:', error.message);
  // Another host already owns the pipe. Stay attached to Chrome, never race for
  // requests, and keep trying so this instance takes over when the owner exits.
  if (!reportedInUse) {
    reportedInUse = true;
    sendToChrome({ type: 'sourcecapsule:host-status', ok: false, error: 'pipe_in_use' });
  }
  if (!listenRetry) listenRetry = setTimeout(listen, LISTEN_RETRY_MS);
});

server.on('listening', () => {
  log('listening on', PIPE, 'pid', process.pid);
  reportedInUse = false;
  sendToChrome({ type: 'sourcecapsule:host-status', ok: true, pipe: PIPE, pid: process.pid });
});

listen();

// Chrome suspends an idle MV3 service worker after ~30s. An inbound native message
// resets that timer, so the host, not the worker, owns the keepalive.
setInterval(() => sendToChrome({ type: 'sourcecapsule:heartbeat', at: Date.now() }), 20000);

readChromeMessages((message) => {
  if (message && message.type === 'sourcecapsule:heartbeat') return;
  if (message && message.id) replyToCli(String(message.id), message);
  else log('unrouted message from chrome:', JSON.stringify(message).slice(0, 200));
});

