}
const tree = execFileSync("git", ["mktree"], { cwd: root, input: treeInput, encoding: "utf8" }).trim();

let parent = null;
try { parent = git("rev-parse", "--verify", "refs/heads/release"); } catch (e) { parent = null; }

const args = ["commit-tree", tree, "-m", "release: v" + version];
